function makeConfig(overrides: Partial<AgentConfig> = {}): AgentConfig {
  return {
    ...DEFAULT_CONFIG,
    timeoutMinutes: 10,
    ...overrides,
    review: {
      ...DEFAULT_CONFIG.review,
      enableReachability: false,
      ...((overrides.review || {}) as Record<string, unknown>),
    },
  };
}

